// Bolt sprites for mods, v1.0.0. GENERATED by brand/bolt-sprites/tools/build.py: edit design.py, not this file.
// Copy this file into your mod's hooks/ folder (mods install on their own, so they cannot import from brand/).
// Rules (brand/BRAND.md): pink is the antenna light only, blush the cheeks only. Never recolour, rotate or stretch.
// Never draw Bolt over a safety hold, and never in a toast (toasts are uncoloured text).

export const BOLT_PALETTE = {
  B: '#C8F53C',
  S: '#9BC21A',
  O: '#FF5C8A',
  K: '#FF8FB1',
  E: '#101114',
  W: '#FBFBF8',
  G: '#8E95A3',
} as const

export type BoltSize = 'small' | 'tiny'
export type BoltSmallPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep' | 'sweat' | 'think' | 'egg' | 'egg-wobble-l' | 'egg-wobble-r' | 'egg-crack-1' | 'egg-crack-2' | 'egg-crack-3' | 'egg-hatch'
export type BoltTinyPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep'
export type BoltPose = BoltSmallPose | BoltTinyPose

/** One text cell: a character and its colours (absent = the surface's own). */
export type BoltCell = { ch: string; fg?: string; bg?: string }

/** Pixel rows: one palette letter per pixel, '.' empty. Heights are even (two pixel rows per cell). */
export const BOLT_SPRITES = {
  small: {
    'idle': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'run1': ['...OO.....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', 'SS......SS'],
    'run2': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', '...SSSS...'],
    'jump': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEBBBB', '.SSSSSSSS.', '...S..S...'],
    'crash': ['......OO..', '.....S....', '..BBBBBB..', '.BBBBBBBB.', 'BEBEBBEBEB', 'BBEBBBBEBB', 'BEBEBBEBEB', 'BBBBEEBBBB', '.SSSSSSSS.', 'SS......SS'],
    'cheer': ['S...OO...S', 'S...SS...S', 'SBBBBBBBBS', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBEEEEBBB', '.SSSSSSSS.', '..SS..SS..'],
    'sleep': ['....SS....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBBBBBBBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBBBBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'sweat': ['....OO....', '....SS...G', '..BBBBBB.G', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEEBBB', '.SSSSSSSS.', '..SS..SS..'],
    'think': ['....OO....', '....SS....', '..BBBBBB..', '.BBWEBWEB.', 'BBBEEBEEBB', 'BBBBBBBBBB', 'BKKBBBBKKB', 'BBBBBEBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'egg': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-wobble-l': ['...OO.....', '...SS.....', '..BWBB....', '.BWBBBB...', '.BBBBBB...', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-wobble-r': ['.....OO...', '.....SS...', '....BWBB..', '...BWBBBB.', '...BBBBBB.', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-1': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBBBBBB.', '.BBEBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-2': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBEBBBB.', '.BBEBEBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-3': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBEBEBB.', '.BBEBEBES.', '..BBBBBS..', '...SSSS...'],
    'egg-hatch': ['......OO..', '......SS..', '....BWBBBB', '....B.B.B.', '..........', '..........', '.B.B.B.BB.', '.BSSSSSSB.', '..BBBBBS..', '...SSSS...'],
  },
  tiny: {
    'idle': ['.O.', 'BEB', 'BBB', 'S.S'],
    'run1': ['.O.', 'BEB', 'BBB', 'S.S'],
    'run2': ['.O.', 'BEB', 'BBB', '.S.'],
    'jump': ['.O.', 'BEB', 'BBB', '.S.'],
    'crash': ['...', '.SO', 'BEB', 'SSS'],
    'cheer': ['SOS', 'BEB', 'BBB', 'S.S'],
    'sleep': ['.S.', 'BSB', 'BBB', 'S.S'],
  },
} as const

/** Letters drawn over a whole cell (cell coordinates). */
const GLYPHS: Record<string, readonly { row: number; col: number; ch: string; color: keyof typeof BOLT_PALETTE }[]> = {
  'small/sleep': [{ row: 0, col: 8, ch: 'z', color: 'G' }],
}

/** The two run frames, in order. Swap them about every 120 ms while running. */
export const BOLT_RUN = ['run1', 'run2'] as const

function colour(key: string | undefined): string | undefined {
  if (key === undefined || key === '.') return undefined
  return (BOLT_PALETTE as Record<string, string>)[key]
}

/**
 * Packs a pose into half-block text cells: rows / 2 lines of `cols` cells.
 * Terminal: draw with Raster (see hatchling's rasterCells). Desktop: one fixed-width cell per character.
 */
export function boltCells(size: 'small', pose: BoltSmallPose): BoltCell[][]
export function boltCells(size: 'tiny', pose: BoltTinyPose): BoltCell[][]
export function boltCells(size: BoltSize, pose: BoltPose): BoltCell[][] {
  const rows: readonly string[] = (BOLT_SPRITES[size] as Record<string, readonly string[]>)[pose] ?? []
  const out: BoltCell[][] = []
  for (let r = 0; r + 1 < rows.length; r += 2) {
    const top = rows[r] ?? ''
    const bottom = rows[r + 1] ?? ''
    const line: BoltCell[] = []
    for (let c = 0; c < top.length; c += 1) {
      const t = colour(top[c])
      const b = colour(bottom[c])
      if (t === undefined && b === undefined) line.push({ ch: ' ' })
      else if (b === undefined) line.push({ ch: '\u2580', fg: t })
      else if (t === undefined) line.push({ ch: '\u2584', fg: b })
      else if (t === b) line.push({ ch: '\u2588', fg: t })
      else line.push({ ch: '\u2580', fg: t, bg: b })
    }
    out.push(line)
  }
  for (const glyph of GLYPHS[`${size}/${pose}`] ?? []) {
    const line = out[glyph.row]
    if (line !== undefined && glyph.col < line.length) line[glyph.col] = { ch: glyph.ch, fg: BOLT_PALETTE[glyph.color] }
  }
  return out
}

/** Merges a row of cells into runs of one style, for coloured Text spans. */
export function boltRuns(line: readonly BoltCell[]): BoltCell[] {
  const runs: BoltCell[] = []
  for (const cell of line) {
    const last = runs[runs.length - 1]
    if (last !== undefined && last.fg === cell.fg && last.bg === cell.bg) last.ch += cell.ch
    else runs.push({ ...cell })
  }
  return runs
}

files.hooks/map.ts:
// The mission map: the main loop and every subagent as nodes, handoffs as
// edges, drawn as one SVG for the surfaces that draw vectors. It is a still
// picture: the desktop re-sets an interactive frame on every render pass of a
// hook that ticks, so there is no pulse and no tooltip; the full tasks go in
// the alt text. Its source depends on the mission's shape alone, never on the
// clock, so a tick redraws the same bytes.

import type { AntFarmAnt } from '../types'

export type MapNode = {
  id: string
  n?: number
  status: AntFarmAnt['status']
  parentId?: string
  /** The task, shortened for the label. Already cleaned. */
  label: string
  /** The task in full, for the tooltip. Already cleaned. */
  title: string
}

/** Nodes at most; the rest are counted. */
export const MAP_NODES_MAX = 10
const LABEL_MAX = 24
/** About one label character at the map's face, in CSS pixels. */
const CHAR_PX = 7
/** The map's own colours: it draws in a frame of its own, where theme keys do not reach; these read on light and dark. */
export const MAP_COLORS = { text: '#8b949e', running: '#58a6ff', done: '#3fb950', failed: '#f85149' } as const
const COLUMN = 200
const ROW = 22
const LEFT = 20
const TOP = 30
const LABEL_DX = 14

export function esc(s: string): string {
  return s.replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch] ?? ch)
}

function short(s: string): string {
  const chars = [...s]
  return chars.length > LABEL_MAX ? `${chars.slice(0, LABEL_MAX - 1).join('')}…` : s
}

/** The nodes in mission order, at most `max`, a parent kept only when it is among them. */
export function mapNodes(list: readonly AntFarmAnt[], clean: (s: string) => string, max = MAP_NODES_MAX): { nodes: MapNode[]; hidden: number } {
  const sorted = [...list].sort((a, b) => (a.n ?? Number.MAX_SAFE_INTEGER) - (b.n ?? Number.MAX_SAFE_INTEGER) || a.startedAt - b.startedAt)
  const shown = sorted.slice(0, max)
  const ids = new Set(shown.map(a => a.id))
  const nodes = shown.map(a => {
    const task = clean(a.task)
    return {
      id: a.id,
      ...(a.n !== undefined ? { n: a.n } : {}),
      status: a.status,
      ...(a.parentId !== undefined && ids.has(a.parentId) ? { parentId: a.parentId } : {}),
      label: short(task),
      title: task,
    }
  })
  return { nodes, hidden: sorted.length - shown.length }
}

/** The SVG: a tree from the main loop, one column per depth, one row per node; running nodes pulse. */
export function missionMap(nodes: readonly MapNode[], hidden = 0): { source: string; alt: string; width: number; height: number } {
  const children = new Map<string | undefined, MapNode[]>()
  for (const node of nodes) children.set(node.parentId, [...(children.get(node.parentId) ?? []), node])
  const placed: { node: MapNode; depth: number; row: number }[] = []
  let row = 1
  const visit = (parent: string | undefined, depth: number) => {
    for (const node of children.get(parent) ?? []) {
      placed.push({ node, depth, row })
      row += 1
      visit(node.id, depth + 1)
    }
  }
  visit(undefined, 1)
  const maxDepth = Math.max(1, ...placed.map(p => p.depth))
  const labelOf = (node: MapNode) => `${node.n !== undefined ? `#${node.n} ` : ''}${node.label}`
  // Wide enough for the longest label in the last column, so nothing is cut at the right edge.
  const rightEdge = Math.max(LEFT + LABEL_DX + 9 * CHAR_PX, ...placed.map(p => LEFT + p.depth * COLUMN + LABEL_DX + [...labelOf(p.node)].length * CHAR_PX))
  const width = rightEdge + 16
  const height = TOP + (row + (hidden > 0 ? 1 : 0)) * ROW
  const x = (depth: number) => LEFT + depth * COLUMN
  const y = (r: number) => TOP + r * ROW
  const at = new Map(placed.map(p => [p.node.id, p] as const))
  const parts: string[] = []
  parts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" font-family="ui-monospace, SFMono-Regular, Menlo, Consolas, monospace" font-size="11">`,
  )
  // Edges leave a parent from its bottom and arrive at a child from its left, so none runs through a label.
  parts.push(`<g stroke="${MAP_COLORS.text}" stroke-width="1.5" fill="none" stroke-opacity="0.6">`)
  for (const p of placed) {
    const from = p.node.parentId !== undefined ? at.get(p.node.parentId) : undefined
    const x1 = from !== undefined ? x(from.depth) : x(0)
    const y1 = (from !== undefined ? y(from.row) : y(0)) + 8
    const x2 = x(p.depth) - 8
    const y2 = y(p.row)
    parts.push(`<path d="M${x1} ${y1} C${x1} ${y1 + 14}, ${x2 - 24} ${y2}, ${x2} ${y2}"/>`)
  }
  parts.push('</g>')
  // The main loop's label sits above its node, out of the edges' way.
  parts.push(`<circle cx="${x(0)}" cy="${y(0)}" r="8" fill="none" stroke="${MAP_COLORS.text}" stroke-width="2"/>`)
  parts.push(`<text x="${x(0) - 8}" y="${y(0) - 13}" fill="${MAP_COLORS.text}">main loop</text>`)
  for (const p of placed) {
    const color = p.node.status === 'running' ? MAP_COLORS.running : p.node.status === 'failed' ? MAP_COLORS.failed : MAP_COLORS.done
    // A running node wears a halo in place of a pulse: a still picture cannot move.
    const halo = p.node.status === 'running' ? `<circle cx="${x(p.depth)}" cy="${y(p.row)}" r="11" fill="none" stroke="${color}" stroke-opacity="0.45" stroke-width="2"/>` : ''
    parts.push(
      `<g>${halo}<circle cx="${x(p.depth)}" cy="${y(p.row)}" r="7" fill="${color}"/>` +
        `<text x="${x(p.depth) + LABEL_DX}" y="${y(p.row) + 4}" fill="${MAP_COLORS.text}">${esc(labelOf(p.node))}</text></g>`,
    )
  }
  if (hidden > 0) parts.push(`<text x="${x(1)}" y="${y(row) + 4}" fill="${MAP_COLORS.text}">+${hidden} more</text>`)
  parts.push('</svg>')
  const running = nodes.filter(n => n.status === 'running').length
  const failed = nodes.filter(n => n.status === 'failed').length
  const done = nodes.length - running - failed
  const tasks = placed.map(p => `#${p.node.n ?? '?'} ${p.node.title}${p.node.parentId !== undefined ? ` (from #${at.get(p.node.parentId)?.node.n ?? '?'})` : ''}: ${p.node.status}`).join('; ')
  const alt = `Mission map: the main loop and ${nodes.length + hidden} subagents, ${running} running, ${done} done, ${failed} failed. ${tasks}`.slice(0, 900)
  return { source: parts.join(''), alt, width, height }
}

files.types/index.d.ts:
// The values ant-farm keeps in $.state for the session. Plain JSON data:
// the host holds them across a hot reload, and every drawing that reads one
// is drawn again when it changes. Fields added after 0.1.1 are optional: a
// value kept by an older version lacks them, and the code treats absent as empty.

/** Tokens and estimated spend of one model loop (a subagent, the main loop, the rest). */
export type AntFarmUsage = {
  /** Model requests that came back with a response. */
  requests: number
  /** Every token the requests reported: input, output, cache reads and cache writes. */
  tokens: number
  /** Estimated US dollars for the tokens whose model is in the price table. */
  costUsd: number
  /** Tokens from models the price table does not know (their cost shows as "?"). */
  unpricedTokens: number
}

export type AntFarmStatus = 'running' | 'done' | 'failed'

/** One subagent of this session: one ant. */
export type AntFarmAnt = {
  /** The agent id `agent.spawn` answered; every loop event carries it. */
  id: string
  /** The Agent call's short description of the task. */
  task: string
  /** The agent type (`Explore`, `general-purpose`, a plugin's agent). */
  type: string
  /** The model the agent runs on, as the API last reported it. */
  model: string
  status: AntFarmStatus
  /** `$.clock.now()` milliseconds. */
  startedAt: number
  endedAt?: number
  usage: AntFarmUsage
  /** When it last started or answered a request: an ant silent for long stops the clock. */
  lastActiveAt?: number
  /** Started by a workflow script: never listed by `$.agent.list()`. */
  isWorkflow?: boolean
  /** Its number in the mission, from 1 in order of start; the cards and the timeline cite it. */
  n?: number
  /** The id of the agent whose loop started it; absent when the main loop did. */
  parentId?: string
  /** Tokens of its last model requests, oldest first, at most 24: the card's sparkline. */
  history?: number[]
  /** Tool calls it made (every tool). */
  tools?: number
  /** Of those, calls that wrote a file (Edit, Write, MultiEdit, NotebookEdit). */
  edits?: number
  /** Tool calls that failed or were refused. */
  errors?: number
}

/** Usage outside the subagents: the main loop, and loops no agent list names (engine forks). */
export type AntFarmLoops = { main: AntFarmUsage; other: AntFarmUsage }

/** The budget level last announced and the budget it was measured against. */
export type AntFarmAlarm = { level: number; budgetUsd: number }

/** The main loop's current turn. */
export type AntFarmTurn = { isRunning: boolean; startedAt: number }

export type AntFarmView = {
  /** Draw the compact list inside the band: the pane was wanted but could not be placed. */
  isListInBand: boolean
  /** Finished subagents drawn as full cards instead of one line each. */
  isFinishedExpanded: boolean
  /** The person closed the pane by hand: do not open it again unasked this session. */
  isClosedByHand: boolean
  /** The pane already opened once unasked: it never does again this session. */
  hasOpenedUnasked: boolean
  /** The subagent whose inspector is open, by id; absent for none. */
  selectedId?: string
  /** The activity timeline shows its long form (40 rows) instead of 12. */
  isTimelineExpanded?: boolean
  /** The activity timeline is folded away. */
  isTimelineHidden?: boolean
  /** The mission map is folded away. */
  isMapHidden?: boolean
}

/** What one row of the activity timeline records. */
export type AntFarmEventKind = 'spawn' | 'handoff' | 'tool' | 'file' | 'done' | 'failed' | 'error' | 'warning'

/** One row of the activity timeline: something a subagent did, or something that happened to it. */
export type AntFarmEvent = {
  /** `$.clock.now()` milliseconds. */
  at: number
  kind: AntFarmEventKind
  /** The subagent it concerns; absent for a session-wide note (the budget alarm). */
  agentId?: string
  /** The row's words: a tool and what it touched, a task, a reason. Untrusted: cleaned when drawn. */
  text: string
  /** A second part drawn after the text: an error's first words, a refusal's reason. Untrusted. */
  detail?: string
}

declare module 'claude-code' {
  interface PluginState {
    'ant-farm': {
      ants: AntFarmAnt[]
      loops: AntFarmLoops
      turn: AntFarmTurn
      /** The budget level announced (0 under, 1 past the budget, 2 past twice it); it only rises until the budget changes or /clear. */
      alarm: AntFarmAlarm
      /** Claude Code's own cost estimate for the session (what /cost shows, at list prices), or null where unavailable. */
      engineUsd: number | null
      view: AntFarmView
      /** The activity timeline, oldest first, at most 80 rows; older rows leave. */
      events: AntFarmEvent[]
    }
  }
}
